INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Sind Mockups in der Regel interaktiv?', 2, '[{"text": "Nein", "correct": true, "because": "Sie sind statisch"}, {"text": "Ja", "correct": false, "because": "Interaktivität ist für Prototypen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich primär mit einem Mockup?', 3, '[{"text": "Visuelle Darstellung", "correct": true, "because": "Fokus auf Design und Layout"}, {"text": "Funktionalität testen", "correct": false, "because": "Das macht ein Prototyp"}, {"text": "Code generieren", "correct": false, "because": "Nicht Zweck eines Mockups"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente gehören typischerweise in ein Mockup?', 5, '[{"text": "Farben und Typografie", "correct": true, "because": "Definiert das Aussehen"}, {"text": "Platzhalter für Inhalte", "correct": true, "because": "Simuliert reale Daten"}, {"text": "Klickbare Buttons", "correct": false, "because": "Interaktivität fehlt"}, {"text": "Datenbankanbindung", "correct": false, "because": "Nicht Teil eines statischen Designs"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Mockups zeigen das endgültige Design. b) Sie sind schneller als Wireframes erstellt.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Mockups sind detailliert, Wireframes schneller"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei einem Mockup, wenn ich nur das Design prüfen will?', 4, '[{"text": "Funktionale Logik", "correct": true, "because": "Nicht Teil eines Mockups"}, {"text": "Farbschema", "correct": false, "because": "Kern des Designs"}, {"text": "Layoutstruktur", "correct": false, "because": "Wichtig fürs Design"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein Mockup auch Code enthält?', 2, '[{"text": "Nein", "correct": true, "because": "Es ist rein visuell"}, {"text": "Ja", "correct": false, "because": "Code ist für Prototypen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Tool ist für Mockups am besten geeignet?', 3, '[{"text": "Figma", "correct": true, "because": "Bietet detaillierte Design-Optionen"}, {"text": "VS Code", "correct": false, "because": "Das ist für Coding"}, {"text": "Postman", "correct": false, "because": "Für API-Tests"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte sollte ich in einem Mockup für ein Dashboard berücksichtigen?', 5, '[{"text": "Widget-Positionen", "correct": true, "because": "Definiert die Struktur"}, {"text": "Farbkodierung", "correct": true, "because": "Verbessert Lesbarkeit"}, {"text": "Datenbankzugriff", "correct": false, "because": "Nicht visuell relevant"}, {"text": "Backend-Logik", "correct": false, "because": "Außerhalb des Mockup-Bereichs"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Mockups sind detaillierter als Wireframes. b) Sie ersetzen Prototypen. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Prototypen testen Funktionalität"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei einem Mockup für eine App unwichtig?', 4, '[{"text": "Visuelle Hierarchie", "correct": false, "because": "Wichtig für Nutzerführung"}, {"text": "Farben", "correct": false, "because": "Bestimmt die Ästhetik"}, {"text": "API-Integration", "correct": true, "because": "Nicht Teil eines statischen Designs"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Dienen Mockups auch zur Funktionalitätsprüfung?', 2, '[{"text": "Nein", "correct": true, "because": "Nur Design, keine Funktion"}, {"text": "Ja", "correct": false, "because": "Das ist für Prototypen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Tools eignen sich gut für Mockups?', 4, '[{"text": "Adobe XD", "correct": true, "because": "Fokus auf Design"}, {"text": "Sketch", "correct": true, "because": "Beliebt für UI-Entwürfe"}, {"text": "Eclipse", "correct": false, "because": "Für Entwicklung, nicht Design"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Mockups nur für Designer sind. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch für Stakeholder und Devs nützlich"}, {"text": "Ja", "correct": false, "because": "Breitere Zielgruppe"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei einem Mockup für eine Website?', 3, '[{"text": "Navigationselemente", "correct": true, "because": "Kern der Benutzbarkeit"}, {"text": "Datenfluss", "correct": false, "because": "Nicht visuell"}, {"text": "Serverantwort", "correct": false, "because": "Technische Ebene"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Mockups nutzen echte Daten. b) Sie simulieren nur das Aussehen.', 3, '[{"text": "Nur b) stimmt", "correct": true, "because": "Mockups verwenden Platzhalter"}, {"text": "Beides stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "b) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Bestandteile sind für ein Mockup eines Formulars entscheidend?', 5, '[{"text": "Felder und Labels", "correct": true, "because": "Zeigen die Struktur"}, {"text": "Farben und Abstände", "correct": true, "because": "Bestimmen die Optik"}, {"text": "Eingabevalidierung", "correct": false, "because": "Funktionale Ebene"}, {"text": "Datenverarbeitung", "correct": false, "because": "Nicht im Mockup enthalten"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei einem Mockup für ein statisches Layout?', 3, '[{"text": "Benutzerinteraktion", "correct": true, "because": "Nicht Teil des Designs"}, {"text": "Typografie", "correct": false, "because": "Wichtig für Lesbarkeit"}, {"text": "Farbanpassung", "correct": false, "because": "Kern des visuellen Entwurfs"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal mit Mockups? Sind sie grobe Skizzen?', 3, '[{"text": "Nein", "correct": true, "because": "Sie sind detailliert, anders als Wireframes"}, {"text": "Ja", "correct": false, "because": "Wireframes sind die groben Skizzen"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Mockups Feedback von Nutzern einholen können?', 2, '[{"text": "Ja", "correct": true, "because": "Visuelle Rückmeldung möglich"}, {"text": "Nein", "correct": false, "because": "Design kann geprüft werden"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Element ist bei einem Mockup für ein mobiles Design entscheidend?', 4, '[{"text": "Responsives Layout", "correct": true, "because": "Passt sich der Bildschirmgröße an"}, {"text": "Datenbankstruktur", "correct": false, "because": "Nicht visuell"}, {"text": "Serverlogik", "correct": false, "because": "Technische Ebene"}]');
